function toggleView(){document.activeElement?.blur();if(photo){toast('Close the field camera before switching view.');return;}view=view==='third'?'first':'third';player.view=view;orbitYaw=0;clearInput();applyZoom();}
addEventListener('keydown',e=>{
  if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)&&e.code!=='Escape')return;
  if(!m.started||m.ended)return;
  // Player already owns Escape even while disabled in vehicle mode.
  if(!$('dialog').hidden)return;
  if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&$('mission-panel').classList.contains('expanded'))toggleTasks(false);
  if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&m.aboard){e.preventDefault();document.activeElement?.blur();keys.add(e.code);if(m.vehicle.parking&&!e.repeat&&['KeyW','KeyS','ArrowUp','ArrowDown'].includes(e.code))toast('Parking brake is set. Click Release brake or press P, then use WASD / arrows.');}
  if(e.repeat)return;
  if(e.code==='KeyV'&&m.aboard)toggleView();
  if(e.code==='KeyP'&&m.aboard)toggleParking();
  if(e.code==='KeyE'&&m.aboard&&performance.now()>inputLockUntil){e.preventDefault();run('exit');}
  if((e.code==='ShiftLeft'||e.code==='ShiftRight')&&m.aboard){m.eco=!m.eco;toast(m.eco?'Eco mode limits speed and reduces traction energy use.':'Normal drive mode.');}
  if(e.code==='KeyM')toggleMap();if(e.code==='KeyT')toggleTasks();if(e.code==='KeyH')help();if(e.code==='KeyJ')openJournal();if(e.code==='Equal'||e.code==='NumpadAdd')zoom(-1);if(e.code==='Minus'||e.code==='NumpadSubtract')zoom(1);
});
